    await post('/projects/1/tasks', { title: 'Normal again' });
    allRows = rows(await get('/projects/1'));
    assert.equal(selected(allRows[3], 'task-priority-5'), 'Normal');
    await post('/projects/1/rename', { name: 'Renamed project' });
