    assert.equal(defaultPriority(restored), 'High');
    assert.doesNotMatch(restored, /<select id="default-task-priority"[^>]* disabled/);
    assert.deepEqual(rows(restored), allRows);
    await post('/projects/1/tasks', { title: 'After restore' });
