      ['2024-02-29', '', [4, 5, 6]],
      ['2024-02-28', '2024-03-01', [3, 4, 5]],
      ['2024-02-29', '2024-02-29', [4]],
      ['0001-01-01', '9999-12-31', [2, 3, 4, 5, 6]],
    ]) {
      for (const filter of ['All', 'Open', 'Completed']) {
        for (const priorityFilter of ['All', 'Low', 'Normal', 'High']) {
